select count(*)
from user_file
where user_id = #{userId}
  and parent_id = #{targetId}
  and file_name = (select uf.file_name from user_file uf where id = #{id});

with recursive tree as (select t1.id, t1.media_category, t1.object_id from user_file t1 where id in
#{id}
union all select t2.id, t2.media_category, t2.object_id from tree t1 inner join user_file t2 on t1.id = t2.parent_id # where t2.media_category != 0 ) select object_id, id, media_category from tree where media_category not in (-1);
